import{_ as e,o as a,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Set Credit","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subscription-billing/3-9-7-set-credit/spec.md","filePath":"feature/subscription-billing/3-9-7-set-credit/spec.md"}'),r={name:"feature/subscription-billing/3-9-7-set-credit/spec.md"};function c(h,t,o,d,s,l){return a(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="uc-—-set-credit" tabindex="-1">UC — Set Credit <a class="header-anchor" href="#uc-—-set-credit" aria-label="Permalink to &quot;UC — Set Credit&quot;">​</a></h1><p>&gt; <strong>BA hiện hành 2026-10-19:</strong> Owner cấu hình mức mặc định Agency và hạn mức từng thành viên Manager/Creator; Owner không có hạn mức cá nhân. Đây là trần chi tiêu, không phân bổ ví: tổng trần được vượt quỹ chung, nhưng tổng thực chi không được vượt số dư. Giữ cấu hình qua kỳ subscription, reset usage theo kỳ. Quyết định này thay giới hạn tổng hạn mức/soft warning trong các mục lịch sử dưới đây. Xem <a href="./../member-credit/spec.html">đặc tả hiện hành</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.9.7</td></tr><tr><td>Feature</td><td>Set Credit</td></tr><tr><td>Domain</td><td>Subscription (FR 3.9)</td></tr><tr><td>Role</td><td>OWNER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Owner đặt hạn mức tiêu credit cho Creator — cơ chế kiểm soát chi phí AI nội bộ Agency.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Owner, tôi muốn đặt hạn mức credit AI cho từng Creator, để kiểm soát chi phí sử dụng AI trong Agency.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Set <code>monthlyLimit</code> cho 1 Creator cụ thể (trong phạm vi tổng credit Agency đang có).</li><li>Creator vượt hạn mức → không generate AI được nữa cho đến tháng sau hoặc được Owner tăng hạn mức.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Trang <code>/agencies/:id/ai-credit</code>, nút &#39;Đặt hạn mức&#39; cạnh mỗi Creator.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATCH /api/v1/agencies/{id}/ai-credit/{creatorId}/limit</span></span>
<span class="line"><span>{ &quot;monthlyLimit&quot;: number }</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;creatorId&quot;, &quot;monthlyLimit&quot; } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Không phải Owner → 403 <code>FORBIDDEN</code>.</li><li><code>monthlyLimit</code> vượt tổng credit Agency hiện có → 400 <code>LIMIT_EXCEEDS_AGENCY_CREDIT</code> (cảnh báo, không chặn cứng nếu Owner muốn cho phép vượt tạm thời — quyết định khi thiết kế).</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Creator đã dùng vượt hạn mức mới đặt (do trước đó chưa có hạn mức) → không rollback usage cũ, hạn mức mới chỉ áp dụng cho phần dùng tiếp theo.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Đặt hạn mức thành công, Creator bị chặn đúng khi vượt.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/08-subscription-billing.html">08-subscription-billing.md</a></p>`,23)])])}const m=e(r,[["render",c]]);export{p as __pageData,m as default};
